#!/usr/bin/env node
/* Generated by tfd-sim-system (web/scripts/templates.mjs). Do not edit here — change it in tfd-sim-system.

   Writes /tfd-config.js for the TFD Sim System pages (/datlich, /datlich-hanoi, /taikhoan, /quanli) from GitHub
   Actions secrets, right before the Pages deploy:
     TFD_SUPABASE_URL       https://<project-ref>.supabase.co
     TFD_SUPABASE_ANON_KEY  the project's anon (public) key — protected by RLS, NOT the service-role key
     TFD_ENVIRONMENT        production | test (optional, default production)
   Both values missing → the pages show "Trang chưa sẵn sàng" and the deploy continues (the rest of the website is
   unaffected). One of them missing or malformed → the deploy stops, so a half-configured page never goes live. */
var fs = require('fs');
var path = require('path');

var OUT = path.join(__dirname, '..', 'tfd-config.js');
var url = (process.env.TFD_SUPABASE_URL || '').trim();
var key = (process.env.TFD_SUPABASE_ANON_KEY || '').trim();
var env = (process.env.TFD_ENVIRONMENT || 'production').trim();

function die(msg) {
  console.error('\n✖ build-tfd-config: ' + msg + '\n');
  process.exit(1);
}

if (!url && !key) {
  fs.writeFileSync(OUT, '/* TFD Sim System chưa được cấu hình cho bản deploy này. */\nwindow.TFD_CONFIG = null;\n');
  console.warn('⚠ build-tfd-config: chưa có TFD_SUPABASE_URL / TFD_SUPABASE_ANON_KEY — trang đặt lịch mới hiển thị "chưa sẵn sàng".');
  process.exit(0);
}
if (!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/.test(url)) die('TFD_SUPABASE_URL không đúng dạng https://<project-ref>.supabase.co');
if (!/^[A-Za-z0-9._-]{20,}$/.test(key)) die('thiếu hoặc sai TFD_SUPABASE_ANON_KEY');
if (/^sb_secret_/.test(key) || /service_role/.test(Buffer.from((key.split('.')[1] || ''), 'base64').toString('utf8'))) {
  die('TFD_SUPABASE_ANON_KEY đang là khóa service_role — tuyệt đối không đưa khóa này lên trang tĩnh.');
}
if (['production', 'test', 'development'].indexOf(env) < 0) die('TFD_ENVIRONMENT phải là production hoặc test');

var config = { supabaseUrl: url.replace(/\/+$/, ''), supabaseAnonKey: key, environment: env };
fs.writeFileSync(OUT, '/* Generated at deploy by tools/build-tfd-config.js — public values only. */\nwindow.TFD_CONFIG = ' + JSON.stringify(config) + ';\n');
console.log('✔ build-tfd-config: tfd-config.js (' + env + ')');
